// ASKOFA Engine - procedural geometry. Meshes are generated by our own
// code (no model files needed for the built-in shapes): interleaved
// position + normal vertices and an index list, ready to upload to the GPU.
#pragma once

#include <vector>

#include "math.hpp"
#include "scene.hpp"

namespace askofa {

struct MeshData {
    std::vector<float> vertices; // x,y,z, nx,ny,nz per vertex
    std::vector<unsigned int> indices;
    size_t vertexCount() const { return vertices.size() / 6; }
};

MeshData makeCubeGeometry();
MeshData makeSphereGeometry(int rings = 16, int sectors = 24);
MeshData makeCylinderGeometry(int sectors = 24);
MeshData makeConeGeometry(int sectors = 24);
MeshData makeTorusGeometry(int rings = 20, int sides = 12);
MeshData makeGroundGeometry(); // flat chunky slab, like a floor tile
MeshData makeMarkerGeometry(); // small wireframe-ish cube for cameras/empties

MeshData geometryFor(ObjectType type);

} // namespace askofa
